return {rwnpc01={id="rwnpc01",dsc="她是在平安小镇长大的孤女，虽然年幼，但十分有主见，总是对未来怀揣着无比的期待。",sex="女",age=10,looks=19,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他是菜来饭馆的管事，正在主持菜来饭馆的厨艺擂台。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="他看起来读过些书的样子，但十分沉迷于酒色。",sex="男",age=23,looks=17,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="他昔年曾是一名刀客，后被仇人追杀身负重伤，为平安小镇的居民所救，后在此安家退隐江湖。",sex="男",age=45,looks=15,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="她是平安小镇长大的居民，外嫁了出去，近年丈夫病逝，无奈又回到了平安小镇。",sex="女",age=38,looks=20,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="盘踞在平安小镇附近的混混，似乎和江采英有些过节。",sex="男",age=45,looks=13,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="盘踞在平安小镇附近的混混，似乎和江采英有些过节。",sex="男",age=45,looks=13,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="附近道观的道长，正襟危坐，十分有气度。",sex="男",age=45,looks=20,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="附近道观的道长，懒懒散散的模样，衣冠不整，看起来没个正经。",sex="男",age=30,looks=24,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="她生得娇小，却总是一副跋扈的模样，身世似乎有些坎坷，骨子里有股骄傲。",sex="女",age=30,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="平安小镇的居民，前些日子前往京城，似乎得到了达官贵人的赏识。",sex="男",age=23,looks=17,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",sex="男",age=30,looks=13,showequip={},withCorpse=0},bsnpc01={id="bsnpc01",dsc="他为人十分老实，少年时本打算考取功名，可惜家道中落，于是学着别人落草为寇，但因为十分老实被赶出了山寨，如今耕田过日子倒也自在。",sex="男",age=29,looks=16,showequip={},withCorpse=0},bsnpc02={id="bsnpc02",dsc="他昔年曾是一名刀客，后被仇人追杀身负重伤，为平安小镇的居民所救，后在此安家退隐江湖。",sex="男",age=45,looks=15,showequip={},withCorpse=0},bsnpc03={id="bsnpc03",dsc="她是平安小镇的居民，在家中排行第二，早年嫁给了一个江湖浪人，后夫君远走江湖再未归来。",sex="女",age=44,looks=18,showequip={},withCorpse=0},bsnpc04={id="bsnpc04",dsc="她身着破旧的粗布衣，身上挂着用线绳穿好的十多双大大小小的草鞋、布鞋。",sex="女",age=45,looks=18,showequip={},withCorpse=0},bsnpc05={id="bsnpc05",dsc="他一副书生模样，但手中却拿着一个沉重的流星锤，虽是有模有样的耍着，但因气力不足，下盘紊乱，常常将流星锤砸入四周的石板，引得周围人群纷纷避让。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc06={id="bsnpc06",dsc="他是平安小镇中出了名的恶霸，仗着家中有人当官平日里作威作福。",sex="男",age=28,looks=18,showequip={},withCorpse=0},bsnpc07={id="bsnpc07",dsc="她刚刚搬到平安小镇，生得颇有几分姿色，故引得临街儿郎思慕不已，扯出一段“倚门回首，却把青梅嗅”的佳话。",sex="女",age=23,looks=20,showequip={},withCorpse=0},bsnpc08={id="bsnpc08",dsc="他梳着一个长长的小辫，手上拿着一把桃木短剑，面目严肃，颇有几分“大侠”的样子。",sex="男",age=11,looks=19,showequip={},withCorpse=0},bsnpc09={id="bsnpc09",dsc="他时常喝得酩酊大醉，听说多年前也曾是浪荡江湖的剑客，后来不知为何埋剑藏名隐居于平安小镇。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc10={id="bsnpc10",dsc="他手中拿着几个铜板，正盯着前方的菜来饭馆，不时往前走两步，又退两步，看起来十分纠结。",sex="男",age=23,looks=17,showequip={},withCorpse=0},bsnpc11={id="bsnpc11",dsc="他是平安小镇的居民，身穿粗布长衣，手中拿着一个鸟笼。鸟笼里关着一只翠鸟，毛色翠兰，十分夺目。",sex="男",age=35,looks=16,showequip={},withCorpse=0},bsnpc12={id="bsnpc12",dsc="他自称是响当当的江湖大侠，身具传奇，懂得天下所有武功。他手中时常抱着剑，装成一副十分冷酷的样子。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc13={id="bsnpc13",dsc="他佝偻着背，手上拿着一个拐杖，正坐在路旁歇息。",sex="男",age=65,looks=15,showequip={},withCorpse=0},bsnpc14={id="bsnpc14",dsc="她个头要比同龄孩童还要小巧些，走起路来摇摇晃晃，手中拿着一个冰糖葫芦，笑嘻嘻的望着你。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc15={id="bsnpc15",dsc="她是平安小镇的居民，父母常年在外，由祖母一手带大，十分懂事。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc16={id="bsnpc16",dsc="他是平安小镇的居民，手中拿着一个鸡腿，胸前的衣襟沾满了油渍。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc17={id="bsnpc17",dsc="她年轻时曾是武林中公认的美人，英雄迟暮，美人自然也有这么一天，自隐居平安小镇后，她除了自怜自哀以外成了统领平安小镇三姑六婆一起八卦的核心之人。",sex="女",age=45,looks=21,showequip={},withCorpse=0},bsnpc18={id="bsnpc18",dsc="她是平安小镇的居民，听闻早年逃荒而来，她的青梅竹马则于半道饿死，致使其一生未嫁。",sex="女",age=56,looks=18,showequip={},withCorpse=0},bsnpc19={id="bsnpc19",dsc="他是村中顽童，父亲是个马商，故小名叫“马儿”，日子久了大家反而忘记了他原本的名字。他跨着一个竹马，正学着戏文的那些江湖豪杰“行侠仗义”。",sex="男",age=10,looks=17,showequip={},withCorpse=0},bsnpc20={id="bsnpc20",dsc="他是平安小镇的居民，有几分小聪明，去年做了点小生意赚了不少钱，在镇中出了名的怕老婆，常常被罚跪搓衣板。",sex="男",age=33,looks=19,showequip={},withCorpse=0},bsnpc21={id="bsnpc21",dsc="他是平安小镇的居民，本是个教书先生，据说年轻时曾经中过举人，但是真是假不得而知。",sex="男",age=55,looks=16,showequip={},withCorpse=0},bsnpc22={id="bsnpc22",dsc="他是一个马贩，常年在外奔波，不久前在去往西域时被沙匪所劫，幸得江湖中的侠客路过救了他一命。可惜他身受重伤，落下了病根，自此不宜远行。",sex="男",age=35,looks=17,showequip={},withCorpse=0},bsnpc23={id="bsnpc23",dsc="他手上拿着一把钉耙，听说自小就想成为游走江湖的大侠，可惜祖上代代务农，故其父不允其出门学艺。",sex="男",age=21,looks=19,showequip={},withCorpse=0},bsnpc24={id="bsnpc24",dsc="他是平安小镇的居民，曾是附近县里头的师爷，公正无私，协助官老爷处理了不少冤案。在镇中颇有几分声望，受到邻里的尊重。",sex="男",age=55,looks=17,showequip={},withCorpse=0},bsnpc25={id="bsnpc25",dsc="他是平安小镇的普通居民，平日里都在田间务农，虽然大字不识几个，却喜欢观摩镇中老者下棋，故而看上去略给人几分聪慧之感。",sex="男",age=24,looks=18,showequip={},withCorpse=0},bsnpc26={id="bsnpc26",dsc="她走起路来颇有几分“婀娜”之感，听闻早年流落风尘被一名侠客所救，如今在这平安小镇里安度余生。",sex="女",age=43,looks=18,showequip={},withCorpse=0},bsnpc27={id="bsnpc27",dsc="他是一个江湖侠客，身后背着一把极为沉重的巨剑，名为“战戈”。他脸上有一道疤痕，不知是从何而来，下巴处许久没有打理的胡渣让他看上去十分沧桑。",sex="男",age=45,looks=23,showequip={},withCorpse=0},bsnpc28={id="bsnpc28",dsc="他是平安小镇的居民，曾在武馆学艺多年，如今在镇中教习些拳脚。",sex="男",age=27,looks=16,showequip={},withCorpse=0},bsnpc29={id="bsnpc29",dsc="他穿着朴素，此时正在安排一些苦力搬运货物。",sex="男",age=35,looks=20,showequip={},withCorpse=0},bsnpc30={id="bsnpc30",dsc="他是马三德的独子，自幼顽皮，跟他父亲一样不喜欢读书，整日从私塾里逃出来胡闹，自称天下没人能够管住他。",sex="男",age=10,looks=20,showequip={},withCorpse=0},bsnpc31={id="bsnpc31",dsc="他本是穷苦人家出生，识不得几个大字，少年时跟随一个药商做学徒，十年后凭借运气发了家，积累了些小财，娶妻生子。自发妻去世后搬离了原本的村子，来到平安小镇居住。",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc32={id="bsnpc32",dsc="他是平安小镇的糖贩，家中养了无数蜜蜂，做出的糖极为甜蜜。他为人亲和，时常会把自己做的各色糖果赠予镇中孩童。",sex="男",age=32,looks=17,showequip={},withCorpse=0},bsnpc33={id="bsnpc33",dsc="他身着破烂衣衫，不知从何而来，一会儿声称自己是“八指神丐”，一会儿又说自己是苏乞儿之徒。他手中端着的一个缺口白碗，据说是祖传宝物。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc34={id="bsnpc34",dsc="他祖上曾是名扬江湖的大侠，多年前偶然路过平安小镇，故在此安家，不涉江湖事多年。",sex="男",age=45,looks=19,showequip={},withCorpse=0},bsnpc35={id="bsnpc35",dsc="浑身黝黑的打铁匠。",sex="男",age=31,looks=18,showequip={},withCorpse=0},bsnpc36={id="bsnpc36",dsc="他穿了一身黑色劲装，眼神灵动，浑身充满了少年人才有的活力。",sex="男",age=23,looks=23,showequip={},withCorpse=0},bsnpc37={id="bsnpc37",dsc="他闲散于江湖，自嘲自己学武不专，所以号“半武”。在平安小镇隐居多年，少有人看到他出招练武，只当是个寻常人，但其内力似乎深不可测。",sex="男",age=45,looks=25,showequip={},withCorpse=0},bsnpc38={id="bsnpc38",dsc="早年靠车马发家，如今生意遍布大江南北。他身材清瘦，两眼微凹，腰间挂着一把老旧的长鞭，据说是年少时所用。",sex="男",age=45,looks=20,showequip={},withCorpse=0}}000000000000000